class RenameIndex(ModelOperation):
    """Rename an index."""

    def __init__(self, model_name, new_name, old_name=None, old_fields=None, new_fields=None):
        if not old_name and not old_fields:
            raise ValueError(
                "RenameIndex requires one of old_name and old_fields arguments to be set."
            )
        if new_name and new_fields:
            raise ValueError(
                "RenameIndex.new_name and new_fields arguments cannot be both set."
            )
        self.model_name = model_name
        self.new_name = new_name
        self.old_name = old_name
        self.old_fields = old_fields
        self.new_fields = new_fields
        super().__init__(model_name)

    @cached_property
    def model_name_lower(self):
        return self.model_name.lower()

    @cached_property
    def old_name_lower(self):
        return self.old_name.lower() if self.old_name else None

    @cached_property
    def new_name_lower(self):
        return self.new_name.lower() if self.new_name else None

    def deconstruct(self):
        kwargs = {
            "model_name": self.model_name,
            "new_name": self.new_name,
        }
        if self.old_name:
            kwargs["old_name"] = self.old_name
        if self.old_fields:
            kwargs["old_fields"] = self.old_fields
        if self.new_fields:
            kwargs["new_fields"] = self.new_fields
        return (self.__class__.__qualname__, [], kwargs)

    def state_forwards(self, app_label, state):
        model_state = state.models[app_label, self.model_name_lower]
        if self.old_fields:
            # Rename an unnamed index for a field or fields.
            self.new_name = self._generate_index_name(model_state, self.new_fields or self.old_fields)
            self.old_name = self._generate_index_name(model_state, self.old_fields)
        # Rename the index.
        if self.old_name not in model_state.options["indexes"]:
            raise ValueError("Index '%s' does not exist in model %s.%s" % (
                self.old_name,
                app_label,
                self.model_name,
            ))
        index = model_state.options["indexes"][self.old_name]
        if self.new_name in model_state.options["indexes"]:
            raise ValueError("Index '%s' already exists in model %s.%s" % (
                self.new_name,
                app_label,
                self.model_name,
            ))
        del model_state.options["indexes"][self.old_name]
        model_state.options["indexes"][self.new_name] = index

